static lstr L1673 = {-1, 5, "E0950"};
static lstr L1674 = {-1, 150, "%q is a copy of an element of %s, so changing it would not change %s; write through the source, `%s[index]%s`, or copy it first with `const copy = %s`"};
static lstr L1675 = {-1, 5, "E0950"};
