static lstr L1683 = {-1, 5, "E0952"};
static lstr L1684 = {-1, 163, "%s.%s takes `mutable Self`, so %s can only be implemented for a type whose contents change in place (a struct, Array, Map, Box, StringBuilder or Generator), not %s"};
static lstr L1685 = {-1, 5, "E0954"};
static lstr L1686 = {-1, 117, "`#[%s, mutable %s]` needs `Arrays.entries(items)` as the source; without the index, write `for (mutable %s of items)`"};
