static lstr L1689 = {-1, 5, "E0954"};
static lstr L1690 = {-1, 71, "`for (mutable ...)` changes the elements of an Array in place, found %s"};
static lstr L1691 = {-1, 5, "E0954"};
static lstr L1692 = {-1, 145, "the source of `for (mutable ...)` must be a variable, a field or an element, so the loop can change it in place; store the array in a local first"};
static lstr L1693 = {-1, 5, "E0955"};
static lstr L1694 = {-1, 146, "the elements of %s are %s, which have no contents to change in place; write `%s[%s] = ...` in a `for (const #[%s, %s] of Arrays.entries(%s))` loop"};
static lstr L1695 = {-1, 5, "E0956"};
static lstr L1696 = {-1, 113, "%q cannot be used inside the loop that changes %s in place; reach its elements through %s, or write an index loop"};
static lstr L1697 = {-1, 5, "E0957"};
static lstr L1698 = {-1, 134, "`for (mutable ...)` is not supported in a function* body yet; change the elements through an index, as in `items[index].field = value`"};
static lstr L1699 = {-1, 5, "E0958"};
static lstr L1700 = {-1, 147, "loop element %q cannot be assigned whole; `mutable` reaches its fields and elements, so assign those, or write an index loop to replace the element"};
