static lstr L1790 = {-1, 417, "\012// Closure environments. A count below zero marks an environment on the\012// caller's stack, which is never counted or freed.\012typedef struct narra_env { int64_t rc; void (*drop)(struct narra_env*); } narra_env;\012static void narra_env_retain(narra_env* e) {\012  if (e && e->rc >= 0) e->rc++;\012}\012static void narra_env_release(narra_env* e) {\012  if (e && e->rc >= 0 && --e->rc == 0) {\012    e->drop(e);\012    narra_free(e);\012  }\012}\012"};
